package com.sahyadri.sahyadripooltrip.service;
import com.sahyadri.sahyadripooltrip.entity.NatureDestination; import com.sahyadri.sahyadripooltrip.repository.NatureDestinationRepository; import org.springframework.core.io.ClassPathResource; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.io.*; import java.nio.charset.StandardCharsets; import java.util.*;
@Service public class NatureDestinationCsvImportService{private static final String FILE="data/INDIA_NATURE_SPECIAL_MASTER.csv"; private final NatureDestinationRepository repo; public NatureDestinationCsvImportService(NatureDestinationRepository r){repo=r;}
@Transactional public ImportResult importAll() throws Exception{ClassPathResource res=new ClassPathResource(FILE);if(!res.exists())throw new IllegalStateException("Nature master CSV not found: "+FILE);int count=0;try(BufferedReader br=new BufferedReader(new InputStreamReader(res.getInputStream(),StandardCharsets.UTF_8))){String h=br.readLine();if(h==null)throw new IllegalStateException("CSV is empty");String line;int row=1;while((line=br.readLine())!=null){row++;if(line.isBlank())continue;List<String> c=parse(line);if(c.size()!=20)throw new IllegalStateException("Invalid nature CSV line "+row+" expected 20 columns, got "+c.size());String id=v(c,0),name=v(c,1),state=v(c,2);if(id==null||name==null||state==null)throw new IllegalStateException("Missing required fields at line "+row);NatureDestination n=repo.findById(id).orElseGet(NatureDestination::new);n.setLocationId(id);n.setName(name);n.setState(state);n.setDistrict(v(c,3));n.setLocality(v(c,4));n.setCategory(v(c,5));n.setSection(v(c,6));n.setDescription(v(c,7));n.setKnownFor(v(c,8));n.setLatitude(num(v(c,9)));n.setLongitude(num(v(c,10)));n.setBestSeason(v(c,11));n.setDifficulty(v(c,12));n.setPopularityTier(v(c,13));n.setPrimarySource(v(c,14));n.setPhotoSourceUrl(v(c,15));n.setInfoSourceUrl(v(c,16));n.setVerificationStatus(v(c,17));n.setLastVerified(v(c,18));n.setRecordStatus(v(c,19));repo.save(n);count++;}}return new ImportResult(count);}
public record ImportResult(int locationCount){} private String v(List<String> c,int i){String s=c.get(i);return s==null||s.trim().isEmpty()?null:s.trim();} private Double num(String s){try{return s==null?null:Double.parseDouble(s);}catch(Exception e){return null;}} private List<String> parse(String l){List<String>a=new ArrayList<>();StringBuilder b=new StringBuilder();boolean q=false;for(int i=0;i<l.length();i++){char ch=l.charAt(i);if(ch=='"'){if(q&&i+1<l.length()&&l.charAt(i+1)=='"'){b.append('"');i++;}else q=!q;}else if(ch==','&&!q){a.add(b.toString());b.setLength(0);}else b.append(ch);}a.add(b.toString());return a;}}
